$message='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$pdo=db();$action=$_POST['action']??'';if($action==='category'){$pdo->prepare('INSERT INTO cafe_categories (name,sort_order,status) VALUES (?, ?, 1)')->execute([trim($_POST['category_name']), (int)$_POST['sort_order']]);$message='دسته‌بندی اضافه شد.';}elseif($action==='delete'){$pdo->prepare('DELETE FROM cafe_items WHERE id=?')->execute([(int)$_POST['id']]);$message='آیتم حذف شد.';}else{$data=[(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']),(int)$_POST['price'],trim($_POST['barcode']),trim($_POST['image']),(int)$_POST['sort_order']];if(!empty($_POST['id'])){$data[]=(int)$_POST['id'];$pdo->prepare('UPDATE cafe_items SET category_id=?,name=?,description=?,price=?,barcode=?,image=?,sort_order=? WHERE id=?')->execute($data);$message='آیتم ویرایش شد.';}else{$pdo->prepare('INSERT INTO cafe_items (category_id,name,description,price,barcode,image,sort_order,status,created_at) VALUES (?,?,?,?,?,?,?,1,UTC_TIMESTAMP())')->execute($data);$message='آیتم اضافه شد.';}}}catch(Throwable $e){$message=$e->getMessage();}}
$cats=db()->query('SELECT * FROM cafe_categories ORDER BY sort_order,id')->fetchAll();$edit=null;if(!empty($_GET['edit'])){$s=db()->prepare('SELECT * FROM cafe_items WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$items=db()->query('SELECT i.*,c.name category_name FROM cafe_items i JOIN cafe_categories c ON c.id=i.category_id ORDER BY c.sort_order,i.sort_order')->fetchAll();page_header('مدیریت کافه', 'admin');
